(async () => {
  const key = Object.keys(localStorage).find(k => k.includes('access.argus'));
  if (!key) return {error: 'no token key', keys: Object.keys(localStorage)};
  let raw = localStorage.getItem(key); let tok = raw;
  try { const j = JSON.parse(raw); tok = j.access_token || j.accessToken || j.token || (j.body && j.body.access_token) || raw; } catch(e) {}
  const r = await fetch('https://access.wevo.ai/admin/credit/reservations?companyId=136&limit=500', {headers: {Authorization: 'Bearer ' + tok}});
  const text = await r.text();
  if (!r.ok) return {status: r.status, text: text.slice(0, 500)};
  const j = JSON.parse(text);
  const rows = Array.isArray(j) ? j : (j.items || j.data || j.reservations || j.results || []);
  const ids = ['8241','8249','8250','8251'];
  const pick = rows.filter(x => ids.some(id => JSON.stringify(x).includes(id)));
  return {status: r.status, total: rows.length, topKeys: Array.isArray(j)?'array':Object.keys(j), sample: rows[0] ? Object.keys(rows[0]) : null, matches: pick};
})()
